const HeroSlider = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const videoRef = useRef<HTMLVideoElement>(null);
  const slides = useMemo(() => [
    { type: 'video', url: 'https://assets.mixkit.co/videos/preview/mixkit-communication-tower-in-a-sunny-day-41616-large.mp4', title: 'Infrastructure Mastery', subtitle: 'Critical infrastructure deployment and site development powering Ethiopia\'s digital transformation.' },
    { type: 'image', url: 'https://images.unsplash.com/photo-1516733968668-dbdce39c46ef?q=80&w=2000&auto=format&fit=crop', title: 'Digital Architecture', subtitle: 'Modernizing operations with high-performance ICT backbones and bespoke system architectures.' },
    { type: 'image', url: 'https://images.unsplash.com/photo-1544654803-b69140b285a1?q=80&w=2000&auto=format&fit=crop', title: 'Power Grid Integration', subtitle: 'Advancing sustainable energy integration and high-voltage engineering for a resilient future.' }
  ], []);

  useEffect(() => {
    const timer = setInterval(() => setCurrentSlide((prev) => (prev + 1) % slides.length), 10000);
    return () => clearInterval(timer);
  }, [slides]);

  const handleVideoLoop = () => { if (videoRef.current && videoRef.current.currentTime >= 5) { videoRef.current.currentTime = 0; videoRef.current.play(); } };

  return (
    <section className="relative h-screen min-h-[700px] w-full bg-slate-900 overflow-hidden">
      <AnimatePresence mode="wait">
        <motion.div key={currentSlide} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: 1.5 }} className="absolute inset-0 overflow-hidden">
          {slides[currentSlide].type === 'video' ? (
            <video ref={videoRef} autoPlay muted playsInline preload="metadata" onTimeUpdate={handleVideoLoop} className="absolute inset-0 w-full h-full object-cover brightness-[0.35]"><source src={slides[currentSlide].url} type="video/mp4" /></video>
          ) : (
            <motion.div 
              className="absolute inset-0 w-full h-full bg-cover bg-center brightness-[0.35] will-change-transform" 
              style={{ backgroundImage: `url(${slides[currentSlide].url})` }} 
              initial={{ scale: 1.25, x: "-2%", y: "-1%" }} 
              animate={{ scale: 1.0, x: "2%", y: "1%" }} 
              transition={{ duration: 12, ease: "linear" }} 
            />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-[#001F3F] via-transparent to-transparent opacity-90"></div>
        </motion.div>
      </AnimatePresence>

      <div className="container mx-auto px-6 relative z-10 h-full flex flex-col justify-center">
        <motion.div key={`text-${currentSlide}`} initial={{ opacity: 0, x: -40 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.5, duration: 0.8 }} className="max-w-4xl">
          <div className="inline-flex items-center gap-3 bg-blue-600/20 backdrop-blur-md border border-white/10 rounded-full px-5 py-2 mb-8">
            <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
            <span className="text-[10px] font-black text-white uppercase tracking-[0.35em]">Infinite Possibilities</span>
          </div>
          <h1 className="text-6xl md:text-9xl font-black text-white leading-[0.85] tracking-tighter mb-8">{slides[currentSlide].title.split(' ')[0]} <br/> <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-emerald-400 italic">{slides[currentSlide].title.split(' ').slice(1).join(' ')}</span></h1>
          <p className="text-lg md:text-2xl text-white/80 mb-12 max-w-2xl leading-relaxed font-medium">{slides[currentSlide].subtitle}</p>
          <div className="flex flex-wrap gap-5">
            <button className="bg-blue-600 hover:bg-blue-700 text-white px-10 py-5 rounded-2xl font-black tracking-widest text-xs flex items-center gap-3 transition-all shadow-2xl active:scale-95">EXPLORE CAPACITY <ArrowRight size={18} /></button>
            <button className="bg-white/10 hover:bg-white/20 backdrop-blur-md text-white px-10 py-5 rounded-2xl font-black tracking-widest text-xs border border-white/20 transition-all">DOWNLOAD PROFILE</button>
          </div>
        </motion.div>
      </div>

      <div className="absolute bottom-12 left-6 z-20 flex gap-4">
        {slides.map((_, i) => (
          <div key={i} onClick={() => setCurrentSlide(i)} className="group cursor-pointer py-4">
            <div className={`h-1.5 transition-all duration-700 rounded-full ${currentSlide === i ? 'w-20 bg-blue-500 shadow-[0_0_20px_rgba(59,130,246,0.8)]' : 'w-8 bg-white/30 group-hover:bg-white/50'}`}></div>
