  items?: { label: string; href: string }[];
  isLink?: boolean;
}

// --- Constants ---
const NAV_CONFIG: NavItem[] = [
  {
    label: 'COMPANY',
    items: [
      { label: 'About Us', href: '#about' },
      { label: 'Our Team', href: '#' }, // Placeholder for future page
