      { label: 'News & Insights', href: '#' }, // Placeholder for future page
      { label: 'Our Clients', href: '#clients' },
      { label: 'Careers', href: '#' } // Placeholder for future page
    ]
  },
  {
    label: 'SERVICES',
    items: [
      { label: 'Telecommunications Engineering', href: '#services' },
      { label: 'Facility & Data Center Solutions', href: '#services' },
      { label: 'Power Engineering', href: '#services' },
      { label: 'ICT and Consultancy', href: '#services' },
      { label: 'Training', href: '#services' },
      { label: 'Industrial Automations', href: '#services' }
    ]
  },
  {
    label: 'PORTFOLIO', // Renamed from PROJECTS
    items: [
      { label: 'Case Studies', href: '#portfolio' },
      { label: 'Featured Projects', href: '#portfolio' },
      { label: 'Client Success Stories', href: '#portfolio' }
    ]
  },
  {
    label: 'SUSTAINABILITY', // New top-level item
    items: [
      { label: 'Our Commitment', href: '#sustainability' },
      { label: 'Environmental Impact', href: '#sustainability' },
      { label: 'Social Responsibility', href: '#sustainability' },
      { label: 'Certifications & Compliance', href: '#sustainability' }
    ]
  },
  {
    label: 'CONTACT US', // Renamed from CONTACT
    isLink: true
  }
];

// --- Components ---

const LogoSymbol = ({ className = "", forceInvert = false }: { className?: string; forceInvert?: boolean }) => (
  <svg viewBox="0 0 100 100" className={className} fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="InfinEth Logo">
    {/* Blue interlocking path - Recreating the "InfinEth" symbol */}
    <path 
      d="M65 25C50 15 30 15 20 30C10 45 15 65 30 75C40 82 55 80 65 70" 
      stroke="var(--infineth-brand-blue)" 
      strokeWidth="14" 
      strokeLinecap="round" 
      className={forceInvert ? "brightness-150 contrast-125" : ""}
    />
    {/* Dark interlocking path */}
    <path 
      d="M35 75C50 85 70 85 80 70C90 55 85 35 70 25C60 18 45 20 35 30" 
      stroke={forceInvert ? "var(--pure-white)" : "var(--text-primary-on-light)"} 
      strokeWidth="14" 
      strokeLinecap="round" 
    />
  </svg>
);

const Brand = ({ isScrolled = false, isFooter = false, className = "" }: { isScrolled?: boolean; isFooter?: boolean; className?: string }) => {
  const isDarkTheme = isFooter || (!isScrolled && !isFooter);

  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <LogoSymbol className="w-10 h-10 md:w-12 md:h-12 shrink-0 transition-transform duration-500 hover:rotate-12" forceInvert={isDarkTheme} />
      <div className="flex flex-col leading-none">
        <span className={`text-2xl md:text-3xl font-black tracking-tighter transition-colors duration-500 ${isDarkTheme ? 'text-pure-white' : 'text-text-primary-on-light'}`}>
          InfinEth
        </span>
        <span className={`text-[8px] md:text-[10px] font-bold tracking-[0.15em] uppercase mt-0.5 transition-colors duration-500 ${isDarkTheme ? 'text-infineth-accent-cyan' : 'text-infineth-brand-blue'}`}>
          Infinite Possibilities
        </span>
      </div>
    </div>
  );
};

const ContactModal = ({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) => (
  <AnimatePresence>
    {isOpen && (
      <div className="fixed inset-0 z-[200] flex items-center justify-center p-6">
        <motion.div 
          initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          className="absolute inset-0 bg-infineth-primary-dark/80 backdrop-blur-sm"
          onClick={onClose}
        />
        <motion.div 
          initial={{ opacity: 0, scale: 0.9, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20 }}
          className="relative bg-pure-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden grid md:grid-cols-2"
        >
          <div className="bg-infineth-brand-blue p-10 text-pure-white flex flex-col justify-between">
            <div>
              <h3 className="text-3xl font-black tracking-tighter mb-4">Let's Connect.</h3>
              <p className="text-text-primary-on-dark text-sm leading-relaxed mb-8">Discuss your next engineering milestone with our expert team.</p>
              <div className="space-y-4">
                <div className="flex items-center gap-3 text-xs font-bold"><Phone size={16} /> +251 11 635 4312</div>
                <div className="flex items-center gap-3 text-xs font-bold"><Mail size={16} /> infineth@infineth.com</div>
                <div className="flex items-center gap-3 text-xs font-bold"><MapPin size={16} /> Addis Ababa, Ethiopia</div>
              </div>
            </div>
            <div className="pt-8 border-t border-pure-white/10 mt-8">
              <span className="text-[10px] font-black tracking-widest uppercase opacity-50">InfinEth Solutions</span>
            </div>
          </div>
          <div className="p-10">
            <form className="space-y-4" onSubmit={(e) => { e.preventDefault(); alert("Enquiry Sent!"); onClose(); }}>
              <input type="text" className="w-full border-b border-neutral-light-grey py-2 focus:border-infineth-brand-blue outline-none text-sm" placeholder="Full Name" required />
              <input type="email" className="w-full border-b border-neutral-light-grey py-2 focus:border-infineth-brand-blue outline-none text-sm" placeholder="Email Address" required />
              <textarea className="w-full border-b border-neutral-light-grey py-2 focus:border-infineth-brand-blue outline-none text-sm h-24 resize-none" placeholder="Message" required></textarea>
              <button className="w-full bg-infineth-primary-dark text-pure-white py-4 rounded-xl font-black text-xs tracking-widest mt-4 hover:bg-infineth-brand-blue transition-all shadow-lg active:scale-95">SEND ENQUIRY</button>
            </form>
          </div>
          <button onClick={onClose} className="absolute top-6 right-6 text-text-secondary-on-light hover:text-text-primary-on-light transition-colors"><X /></button>
        </motion.div>
      </div>
    )}
  </AnimatePresence>
);

const CountUp = ({ value, suffix = "", duration = 2 }: { value: number; suffix?: string; duration?: number }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, amount: 0.5 });

  useEffect(() => {
    if (isInView) {
      let startTime: number;
      const animate = (timestamp: number) => {
        if (!startTime) startTime = timestamp;
        const progress = Math.min((timestamp - startTime) / (duration * 1000), 1);
        setCount(progress * value);
        if (progress < 1) requestAnimationFrame(animate);
      };
      requestAnimationFrame(animate);
    }
  }, [isInView, value, duration]);

  return <span ref={ref} className="tabular-nums">{Math.floor(count).toLocaleString()}{suffix}</span>;
};

const Header = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isContactOpen, setIsContactOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleHashLinkClick = (href: string) => {
    if (href.startsWith('#')) {
      const element = document.querySelector(href);
      if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
      }
    }
    setIsMobileMenuOpen(false); // Always close mobile menu on link click
  };

  return (
    <>
      <header className={`fixed top-0 left-0 w-full z-[100] transition-all duration-500 ${isScrolled ? 'bg-pure-white/95 backdrop-blur-md py-4 shadow-xl border-b border-neutral-light-grey' : 'bg-transparent py-8'}`}>
        <div className="container mx-auto px-6 flex items-center justify-between">
          <div className="cursor-pointer" onClick={() => window.scrollTo({top: 0, behavior: 'smooth'})}><Brand isScrolled={isScrolled} /></div>
          <nav className="hidden lg:flex items-center gap-1">
            {NAV_CONFIG.map((nav) => (
              <div key={nav.label} className="relative px-5 py-2" onMouseEnter={() => !nav.isLink && setActiveMenu(nav.label)} onMouseLeave={() => setActiveMenu(null)}>
                <div onClick={() => nav.isLink && setIsContactOpen(true)} className={`flex items-center gap-1.5 cursor-pointer text-[13px] font-black tracking-widest transition-colors ${isScrolled ? 'text-text-primary-on-light hover:text-infineth-brand-blue' : 'text-text-primary-on-dark hover:text-infineth-accent-cyan'}`}>
                  {nav.label} {!nav.isLink && <ChevronDown size={14} className={`transition-transform duration-300 ${activeMenu === nav.label ? 'rotate-180' : ''}`} />}
                </div>
                {!nav.isLink && (
                  <AnimatePresence>
                    {activeMenu === nav.label && (
                      <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 15 }} className="absolute top-full left-1/2 -translate-x-1/2 mt-2 w-64 bg-pure-white shadow-2xl rounded-2xl border border-neutral-light-grey p-4">
                        <div className="space-y-1">
                          {nav.items?.map((item, idx) => (
                            <a key={idx} href={item.href} onClick={() => { setActiveMenu(null); handleHashLinkClick(item.href); }} className="flex items-center justify-between p-3 rounded-xl hover:bg-neutral-light-grey text-text-secondary-on-light hover:text-infineth-brand-blue transition-all font-bold text-sm group">
                              {item.label} <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-all -translate-x-2 group-hover:translate-x-0" />
                            </a>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                )}
              </div>
            ))}
          </nav>
          <div className="flex items-center gap-4">
            {/* Mobile menu toggle button - hidden when mobile menu is open */}
            {!isMobileMenuOpen && (
              <button onClick={() => setIsMobileMenuOpen(true)} className={`lg:hidden p-3 rounded-2xl shadow-lg transition-all ${isScrolled ? 'bg-infineth-brand-blue text-pure-white' : 'bg-pure-white text-infineth-brand-blue'}`} aria-label="Open Menu">
                <Menu size={20} />
              </button>
            )}
            <button onClick={() => setIsContactOpen(true)} className={`hidden sm:flex items-center gap-2 px-8 py-3 rounded-2xl text-xs font-black tracking-widest transition-all shadow-xl hover:scale-105 active:scale-95 ${isScrolled ? 'bg-infineth-brand-blue text-pure-white hover:bg-infineth-brand-blue-darker' : 'bg-pure-white text-infineth-brand-blue hover:bg-infineth-brand-blue-light'}`}>GET IN TOUCH</button>
          </div>
        </div>
      </header>

      <AnimatePresence>
        {isMobileMenuOpen && (
          <motion.div initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }} className="fixed inset-0 z-[110] bg-infineth-primary-dark p-8 pt-6 lg:hidden flex flex-col">
            {/* Mobile menu header with Brand and Close button */}
            <div className="flex items-center justify-between pb-8 border-b border-pure-white/10 mb-8">
              <Brand isFooter={true} /> {/* Use isFooter for dark theme brand */}
              <button onClick={() => setIsMobileMenuOpen(false)} className="p-3 rounded-2xl bg-infineth-brand-blue text-pure-white shadow-lg active:scale-95" aria-label="Close Menu">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-8 flex-grow overflow-y-auto">
              {NAV_CONFIG.map((nav) => (
                <div key={nav.label} className="space-y-4">
                  <div className="text-pure-white font-black text-2xl tracking-tighter">{nav.label}</div>
                  {!nav.isLink && (
                    <div className="grid grid-cols-1 gap-3 pl-4 border-l border-pure-white/10">
                      {nav.items?.map(item => <a key={item.label} href={item.href} onClick={() => handleHashLinkClick(item.href)} className="text-text-secondary-on-dark font-bold text-lg hover:text-infineth-accent-cyan py-1 transition-colors">{item.label}</a>)}
                    </div>
                  )}
                  {nav.isLink && (
                    <a onClick={() => { setIsMobileMenuOpen(false); setIsContactOpen(true); }} className="text-text-secondary-on-dark font-bold text-lg hover:text-infineth-accent-cyan py-1 transition-colors cursor-pointer">Get in Touch</a>
                  )}
                </div>
              ))}
            </div>
            <button onClick={() => { setIsMobileMenuOpen(false); setIsContactOpen(true); }} className="bg-infineth-brand-blue text-pure-white py-5 rounded-2xl font-black tracking-widest text-sm shadow-2xl active:scale-95 mt-8">CONTACT OUR EXPERTS</button>
          </motion.div>
        )}
      </AnimatePresence>

      <ContactModal isOpen={isContactOpen} onClose={() => setIsContactOpen(false)} />
    </>
