  const slides = useMemo(() => [
    { type: 'video', url: 'https://assets.mixkit.co/videos/preview/mixkit-communication-tower-in-a-sunny-day-41616-large.mp4', title: 'Foundational Resilience', subtitle: 'Leading the way in Telecommunications Infrastructure and Power Systems for Ethiopia.' },
