const LogoSymbol = ({ className = "", forceInvert = false }: { className?: string; forceInvert?: boolean }) => {
  const blueColor = "#006699";
  const charcoalColor = forceInvert ? "#FFFFFF" : "#36454F";
  const cyanColor = "#00CFFF";

  return (
    <svg viewBox="0 0 100 50" className={className} fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="InfinEth Logo">
      <defs>
        <mask id="interlock-mask">
          <rect width="100" height="50" fill="white" />
          {/* Creating an overlap gap to simulate the blue line passing OVER the charcoal line */}
          <path d="M 40 15 L 60 35" stroke="black" strokeWidth="12" strokeLinecap="round" />
        </mask>
      </defs>

      {/* Charcoal Loop (passes under at center) */}
      <path 
        d="M 50 25 C 60 40 85 40 85 25 C 85 10 60 10 50 25 L 15 25" 
        stroke={charcoalColor} 
        strokeWidth="9" 
        strokeLinecap="round" 
        strokeLinejoin="round"
        className="transition-colors duration-500"
        mask="url(#interlock-mask)"
      />

      {/* Blue Loop (passes over at center) */}
      <path 
        d="M 50 25 C 40 10 15 10 15 25 C 15 40 40 40 50 25 L 85 25" 
        stroke={blueColor} 
        strokeWidth="9" 
        strokeLinecap="round" 
        strokeLinejoin="round"
        className="transition-colors duration-500"
      />

      {/* Interlock Correction Point (Blue crossover detail) */}
      <path 
        d="M 45 20 L 55 30" 
        stroke={blueColor} 
        strokeWidth="9" 
        strokeLinecap="round" 
      />
    </svg>
  );
};

