 * Precision recreation of the official interlocking links with tapered geometry and structural depth.
 */
const LogoSymbol = ({ className = "", forceInvert = false }: { className?: string; forceInvert?: boolean }) => {
  const blueColor = "#007BA7"; // Refined blue from official source
  const charcoalColor = forceInvert ? "#FFFFFF" : "#1A1A1A"; // Deep charcoal/black

  return (
    <svg viewBox="0 0 100 100" className={className} fill="none" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="InfinEth Official Logo">
      <defs>
        <mask id="official-interlock-mask">
          <rect width="100" height="100" fill="white" />
          {/* Creating the interlock point: the charcoal line passes OVER the blue line here */}
          <path d="M 55 45 L 75 65" stroke="black" strokeWidth="18" strokeLinecap="round" />
        </mask>
      </defs>

      {/* Blue Link (Passes Under in one spot) */}
      <path 
        d="M 55 25 C 40 10 15 20 15 45 C 15 70 35 85 55 85 L 65 75" 
        stroke={blueColor} 
        strokeWidth="14" 
        strokeLinecap="round" 
        strokeLinejoin="round"
        className="transition-colors duration-500"
      />

      {/* Charcoal Link (Passes Over in the masked spot) */}
      <path 
        d="M 45 75 C 60 90 85 80 85 55 C 85 30 65 15 45 15 L 35 25" 
        stroke={charcoalColor} 
        strokeWidth="14" 
        strokeLinecap="round" 
        strokeLinejoin="round"
        mask="url(#official-interlock-mask)"
        className="transition-colors duration-500"
      />

      {/* Interlock Correction Point (Charcoal crossover detail) */}
      <path 
        d="M 60 50 L 70 60" 
        stroke={charcoalColor} 
        strokeWidth="14" 
        strokeLinecap="round" 
      />
    </svg>
  );
};

