      <LogoSymbol className="w-4 h-4" forceInvert={false} />
      <p className="truncate">ISO 27001:2022 Certification Confirmed: Excellence in Security Engineering</p>
      <div className="hidden md:flex items-center gap-1 group cursor-pointer hover:text-white transition-colors">
        Read Dossier <ArrowRight size={12} className="group-hover:translate-x-1 transition-transform" />
      </div>
    </div>
  </div>
);

const CountUp = ({ value, suffix = "", duration = 2 }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, amount: 0.5 });
  useEffect(() => {
    if (isInView) {
      let start = null;
      const step = (timestamp) => {
        if (!start) start = timestamp;
        const progress = Math.min((timestamp - start) / (duration * 1000), 1);
        setCount(progress * value);
        if (progress < 1) window.requestAnimationFrame(step);
      };
      window.requestAnimationFrame(step);
    }
  }, [isInView, value, duration]);
  return <span ref={ref} className="tabular-nums">{Math.floor(count).toLocaleString()}{suffix}</span>;
};

// --- Page Sections ---

const Header = ({ onOpenContact }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeMenu, setActiveMenu] = useState(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);

