    const handleScroll = () => setIsScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleLink = (href) => {
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
    setIsMobileOpen(false);
  };

  return (
    <>
      <AnnouncementBar />
      <header className={`fixed top-[36px] left-0 w-full z-[100] transition-all duration-500 ${isScrolled ? 'bg-[#001E3C]/98 shadow-2xl py-4' : 'bg-transparent py-8'}`}>
        <div className="container mx-auto px-6 flex items-center justify-between">
          <div className="cursor-pointer" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}><Brand /></div>
          <nav className="hidden lg:flex items-center gap-1">
            {NAV_CONFIG.map((nav) => (
              <div key={nav.label} className="relative px-5 py-2" onMouseEnter={() => !nav.isLink && setActiveMenu(nav.label)} onMouseLeave={() => setActiveMenu(null)}>
                <div onClick={() => nav.isLink && onOpenContact()} className="flex items-center gap-2 cursor-pointer text-[11px] font-black tracking-[0.2em] text-white hover:text-brand-cyan transition-colors uppercase">
                  {nav.label} {!nav.isLink && <ChevronDown size={14} className={`transition-transform duration-300 ${activeMenu === nav.label ? 'rotate-180' : ''}`} />}
                </div>
                {!nav.isLink && (
                  <AnimatePresence>
                    {activeMenu === nav.label && (
                      <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 15 }} className="absolute top-full left-1/2 -translate-x-1/2 mt-2 w-72 bg-white shadow-2xl rounded-2xl p-5 border border-slate-100">
                        <div className="space-y-1">
                          {nav.items.map((item, idx) => (
                            <a key={idx} href={item.href} onClick={(e) => { e.preventDefault(); handleLink(item.href); }} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 text-slate-600 hover:text-brand-blue font-bold text-[13px] group transition-all">
                              {item.label} <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-all -translate-x-2 group-hover:translate-x-0" />
                            </a>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                )}
              </div>
            ))}
          </nav>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileOpen(true)} className="lg:hidden p-3 rounded-xl bg-white/10 text-white"><Menu size={24} /></button>
            <button onClick={onOpenContact} className={`hidden sm:flex items-center gap-2 px-8 py-3 rounded-xl text-[10px] font-black tracking-widest transition-all shadow-xl hover:scale-105 active:scale-95 uppercase ${isScrolled ? 'bg-brand-cyan text-[#001E3C] hover:bg-white' : 'bg-white text-brand-blue hover:bg-slate-50'}`}>GET IN TOUCH</button>
          </div>
        </div>
      </header>

      <AnimatePresence>
        {isMobileOpen && (
          <motion.div initial={{ x: '100%' }} animate={{ x: 0 }} exit={{ x: '100%' }} transition={{ type: "tween", duration: 0.4 }} className="fixed inset-0 z-[150] bg-brand-charcoal text-white flex flex-col p-8">
            <div className="flex items-center justify-between mb-16">
              <Brand forceInvert={true} />
              <button onClick={() => setIsMobileOpen(false)} className="p-3 bg-white/10 rounded-xl"><X size={28} /></button>
            </div>
            <div className="flex-grow space-y-10 overflow-y-auto pb-10">
              {NAV_CONFIG.map((nav) => (
                <div key={nav.label} className="space-y-4">
                  <div className="text-brand-cyan font-black text-xl tracking-widest uppercase flex items-center gap-3">
                    {nav.icon && <nav.icon size={20} className="opacity-50" />}
                    {nav.label}
                  </div>
                  {!nav.isLink && (
                    <div className="grid gap-4 pl-6 border-l border-white/10">
                      {nav.items.map((item, idx) => (
                        <a key={idx} href={item.href} onClick={(e) => { e.preventDefault(); handleLink(item.href); }} className="text-white/60 font-bold hover:text-white transition-colors">{item.label}</a>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
            <button onClick={() => { setIsMobileOpen(false); onOpenContact(); }} className="w-full bg-brand-blue text-white py-6 rounded-2xl font-black tracking-widest uppercase">Start Building</button>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

const HeroSlider = ({ onOpenContact }) => {
  const [current, setCurrent] = useState(0);
  const slides = useMemo(() => [
    { title: 'Foundational Resilience', subtitle: 'Leading Ethiopia in high-altitude Telecom Infrastructure and Power Systems.', img: 'https://images.unsplash.com/photo-1544724569-5f546fd6f2b5?q=80&w=2000&auto=format&fit=crop' },
    { title: 'Digital Convergence', subtitle: 'Modernizing enterprise operations through high-availability ICT architectures.', img: 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?q=80&w=2000&auto=format&fit=crop' },
    { title: 'Industrial Excellence', subtitle: 'Precision electro-mechanical engineering powering Ethiopia\'s growth.', img: 'https://images.unsplash.com/photo-1466611653911-954554ca0a5b?q=80&w=2000&auto=format&fit=crop' }
