import React, { useState, useEffect, useRef, useMemo } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  motion, 
  AnimatePresence, 
  useInView,
  useScroll,
  useTransform
} from 'framer-motion';
import { 
  Globe, 
  ChevronDown, 
  ArrowRight, 
  Menu, 
  X,
  Building2,
  Zap, 
  HardHat,
  Radio,
  Phone,
  Mail,
  MapPin,
  Award,
  Cpu,
  Lightbulb,
  Server,
  Layers,
  ChevronRight,
  CheckCircle2,
  ChevronUp,
  ShieldCheck
} from 'lucide-react';

/**
 * INFINETH SOLUTIONS - FINAL V1.1 DEMO
 * Convergent Excellence & Official Brand Integration
 */

// --- Constants ---
const NAV_CONFIG = [
  {
    label: 'WHO WE ARE',
    icon: Globe,
    items: [
      { label: 'Identity & Impact', href: '#about' },
      { label: 'Impact Portfolio', href: '#portfolio' },
      { label: 'Sustainability', href: '#about' }
    ]
  },
  {
    label: 'INFRASTRUCTURE',
    icon: HardHat,
    items: [
      { label: 'Telecom Engineering', href: '#infrastructure' },
      { label: 'Power & Energy Systems', href: '#infrastructure' },
      { label: 'Operations & Maintenance', href: '#infrastructure' }
    ]
  },
  {
    label: 'INNOVATION',
    icon: Lightbulb,
    items: [
      { label: 'Digital Architectures', href: '#innovation' },
      { label: 'AI, IoT & Software', href: '#innovation' },
      { label: 'Vertical Mobility', href: '#innovation' }
    ]
  },
  {
    label: 'EXCELLENCE',
    icon: Award,
    items: [
      { label: 'Academy & EHS', href: '#excellence' },
      { label: 'Center of Excellence', href: '#excellence' },
      { label: 'Engineering Consultancy', href: '#excellence' }
    ]
  },
  {
    label: 'CONTACT',
    icon: Phone,
    isLink: true
  }
];

const ISO_DATA = [
  { id: "9001", title: "ISO 9001:2015", description: "Quality Management Systems. Demonstration of ability to consistently provide services that meet customer and applicable statutory requirements." },
  { id: "14001", title: "ISO 14001:2015", description: "Environmental Management Systems. Systematic management of environmental footprint and resource efficiency across all site works." },
  { id: "45001", title: "ISO 45001:2018", description: "Occupational Health & Safety. The bedrock of our field operations, ensuring a zero-incident culture for our nationwide workforce." },
  { id: "27001", title: "ISO 27001:2022", description: "Information Security Management. Protecting the digital assets of our clients through rigorous risk-based security controls." },
  { id: "22301", title: "ISO 22301:2019", description: "Business Continuity. Ensuring InfinEth can respond to and recover from disruptive incidents, maintaining national operations." }
];

const PARTNER_LOGOS = [
  "NOKIA", "SAFARICOM", "ETHIO TELECOM", "UN (UNITED NATIONS)", "HUAWEI", "ERICSSON", "ZTE", "GE", "ABB"
];

// --- Sub-Components ---

const LogoSymbol = ({ className = "", forceInvert = false }) => {
  const blueColor = "#006699"; 
  const charcoalColor = forceInvert ? "#FFFFFF" : "#36454F";

  return (
    <svg viewBox="0 0 100 100" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
      <rect width="100" height="100" rx="16" fill={forceInvert ? "rgba(255,255,255,0.08)" : "rgba(0,102,153,0.04)"} />
      <text 
        x="50%" 
        y="52%" 
        dominantBaseline="middle" 
        textAnchor="middle" 
        style={{ font: '900 48px Inter, system-ui, sans-serif' }}
        letterSpacing="-2"
      >
        <tspan fill={blueColor}>I</tspan>
        <tspan fill={charcoalColor}>E</tspan>
      </text>
    </svg>
  );
};

const Brand = ({ forceInvert = true, className = "" }) => (
  <div className={`flex items-center gap-3 ${className}`}>
    <LogoSymbol className="w-10 h-10 md:w-12 md:h-12 shrink-0 transition-transform duration-500 hover:rotate-6" forceInvert={forceInvert} />
    <div className="flex flex-col leading-none text-left">
      <span className={`text-xl md:text-3xl font-black tracking-tighter transition-colors ${forceInvert ? 'text-white' : 'text-brand-charcoal'}`}>InfinEth</span>
      <span className={`text-[7px] md:text-[10px] font-bold tracking-[0.25em] uppercase mt-0.5 ${forceInvert ? 'text-brand-cyan' : 'text-brand-blue'}`}>Infinite Possibilities</span>
    </div>
  </div>
);

const AnnouncementBar = () => (
  <div className="fixed top-0 left-0 w-full h-[36px] bg-brand-emerald z-[120] flex items-center justify-center overflow-hidden border-b border-black/5">
    <div className="container mx-auto px-6 flex items-center justify-center gap-4 text-brand-charcoal font-black text-[10px] tracking-[0.1em] uppercase">
      <LogoSymbol className="w-4 h-4" forceInvert={false} />
      <p className="truncate">ISO 27001:2022 Certification Confirmed: Excellence in Security Engineering</p>
      <div className="hidden md:flex items-center gap-1 group cursor-pointer hover:text-white transition-colors">
        Read Dossier <ArrowRight size={12} className="group-hover:translate-x-1 transition-transform" />
      </div>
    </div>
  </div>
);

const CountUp = ({ value, suffix = "", duration = 2 }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, amount: 0.5 });
  useEffect(() => {
    if (isInView) {
      let start = null;
      const step = (timestamp) => {
        if (!start) start = timestamp;
        const progress = Math.min((timestamp - start) / (duration * 1000), 1);
        setCount(progress * value);
        if (progress < 1) window.requestAnimationFrame(step);
      };
      window.requestAnimationFrame(step);
    }
  }, [isInView, value, duration]);
  return <span ref={ref} className="tabular-nums">{Math.floor(count).toLocaleString()}{suffix}</span>;
};

// --- Trust Bar Component ---

const TrustBar = () => {
  const [showBar, setShowBar] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setShowBar(window.scrollY > 600);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <AnimatePresence>
      {showBar && (
        <motion.div 
          initial={{ y: 100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 100, opacity: 0 }}
          className="fixed bottom-0 left-0 w-full z-[140] bg-brand-charcoal/90 backdrop-blur-xl border-t border-white/10 py-3 shadow-[0_-10px_40px_rgba(0,0,0,0.3)]"
        >
          <div className="flex items-center gap-12 overflow-hidden relative">
            <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-brand-charcoal to-transparent z-10 pointer-events-none"></div>
            <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-brand-charcoal to-transparent z-10 pointer-events-none"></div>

            <div className="flex gap-24 items-center animate-marquee whitespace-nowrap py-1">
              {[...PARTNER_LOGOS, ...PARTNER_LOGOS].map((name, i) => (
                <div key={i} className="flex items-center gap-3 group">
                  <div className="w-1.5 h-1.5 rounded-full bg-brand-cyan/40"></div>
                  <span className="text-[11px] font-black text-white/50 group-hover:text-brand-cyan transition-colors tracking-[0.2em] uppercase">
                    {name}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

// --- Page Sections ---

const Header = ({ onOpenContact }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [activeMenu, setActiveMenu] = useState(null);
  const [isMobileOpen, setIsMobileOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 30);
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleLink = (href: string) => {
    const el = document.querySelector(href);
    if (el) el.scrollIntoView({ behavior: 'smooth' });
    setIsMobileOpen(false);
  };

  return (
    <>
      <AnnouncementBar />
      <header className={`fixed top-[36px] left-0 w-full z-[100] transition-all duration-500 ${isScrolled ? 'bg-[#001E3C]/98 shadow-2xl py-4' : 'bg-transparent py-8'}`}>
        <div className="container mx-auto px-6 flex items-center justify-between">
          <div className="cursor-pointer" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}><Brand /></div>
          <nav className="hidden lg:flex items-center gap-1">
            {NAV_CONFIG.map((nav) => (
              <div key={nav.label} className="relative px-5 py-2" onMouseEnter={() => !nav.isLink && setActiveMenu(nav.label)} onMouseLeave={() => setActiveMenu(null)}>
                <div onClick={() => nav.isLink && onOpenContact()} className="flex items-center gap-2 cursor-pointer text-[11px] font-black tracking-[0.2em] text-white hover:text-brand-cyan transition-colors uppercase">
                  {nav.label} {!nav.isLink && <ChevronDown size={14} className={`transition-transform duration-300 ${activeMenu === nav.label ? 'rotate-180' : ''}`} />}
                </div>
                {!nav.isLink && (
                  <AnimatePresence>
                    {activeMenu === nav.label && (
                      <motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 15 }} className="absolute top-full left-1/2 -translate-x-1/2 mt-2 w-72 bg-white shadow-2xl rounded-2xl p-5 border border-slate-100">
                        <div className="space-y-1">
                          {nav.items?.map((item, idx) => (
                            <a key={idx} href={item.href} onClick={(e) => { e.preventDefault(); handleLink(item.href); }} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 text-slate-600 hover:text-brand-blue font-bold text-[13px] group transition-all">
                              {item.label} <ArrowRight size={14} className="opacity-0 group-hover:opacity-100 transition-all -translate-x-2 group-hover:translate-x-0" />
                            </a>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                )}
              </div>
            ))}
          </nav>
          <div className="flex items-center gap-4">
            <button onClick={() => setIsMobileOpen(true)} className="lg:hidden p-3 rounded-xl bg-white/10 text-white hover:bg-white/20 transition-colors"><Menu size={24} /></button>
            <button onClick={onOpenContact} className={`hidden sm:flex items-center gap-2 px-8 py-3 rounded-xl text-[10px] font-black tracking-widest transition-all shadow-xl hover:scale-105 active:scale-95 uppercase ${isScrolled ? 'bg-brand-cyan text-[#001E3C] hover:bg-white' : 'bg-white text-brand-blue hover:bg-slate-50'}`}>GET IN TOUCH</button>
          </div>
        </div>
      </header>

