const CountUp = ({ value, suffix = "" }: { value: number; suffix?: string }) => {
  const [count, setCount] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true });
  useEffect(() => { if (isInView) { let currentStep = 0; const steps = 120; const increment = value / steps; const timer = setInterval(() => { currentStep++; if (currentStep >= steps) { setCount(value); clearInterval(timer); } else { setCount(prev => prev + increment); } }, 2000 / steps); return () => clearInterval(timer); } }, [isInView, value]);
  return <span ref={ref}>{Number.isInteger(value) ? Math.floor(count) : count.toFixed(1)}{suffix}</span>;
};

